INSERT INTO `about_section_berandas` VALUES (1,'PT Pelayanan Energi Batam','Energi Bagi Negeri','ENERGI BAGI NEGERI (ENERGY FOR THE COUNTRY) merupakan slogan dalam menyampaikan gagasan positif tentang Visi dan Misi PT Pelayanan Energi Batam. Tonton video ini untuk menjelajahi nilai berkelanjutan dari Produk & Inovasi PEB.','image','upload','/storage/about-media/AIueUD4zmruWSWfhEoqmXDJMjIzTqBjNXOZ17Zr9.jpg','DJI_0437.JPG','{\"label\":\"EFISIENSI\",\"value\":\"95%\",\"description\":\"Menjamin tingkat keandalan pasokan energi yang tinggi serta efisiensi operasional yang maksimal untuk mendukung kebutuhan mitra industri dan kelistrikan batam.\"}','{\"label\":\"INOVATIF\",\"value\":\"85%\",\"description\":\"Terus berinovasi dalam pengembangan produk dan layanan energi berkelanjutan demi menciptakan nilai tambah bagi kemajuan negeri.\"}','2026-08-12 22:05:46','2026-11-01 20:51:52');
/*!40000 ALTER TABLE `about_section_berandas` ENABLE KEYS */;
UNLOCK TABLES;

