INSERT INTO `berita_sections` VALUES (1,'Berita & Acara','Informasi terbaru seputar kegiatan, pencapaian, dan kebersamaan keluarga besar PT Pelayanan Energi Batam.','[{\"id\":\"1786604998452\",\"title\":\"RUPS PT Pelayanan Energi Batam Tahun Buku 2025 Berjalan Lancar\",\"subtitle\":\"PT Pelayanan Energi Batam telah melaksanakan Rapat Umum Pemegang Saham (RUPS) Persetujuan Laporan Tahunan dan Pengesahan Laporan Keuangan Tahun Buku 2025, yang berlangsung pada Selasa, 30 Juni 2026.<div><br><\\/div><div>Dalam RUPS tersebut, seluruh agenda rapat memperoleh persetujuan dari para pemegang saham, sebagai bentuk apresiasi atas kinerja Perseroan sepanjang tahun 2025 yang menunjukkan capaian positif serta pengelolaan perusahaan yang akuntabel dan berorientasi pada tata kelola yang baik.<\\/div><div><br><\\/div><div>Persetujuan ini menjadi semangat bagi PT Pelayanan Energi Batam untuk terus meningkatkan kinerja, menghadirkan layanan energi yang andal, serta mendukung pertumbuhan ekonomi dan pembangunan berkelanjutan di Kota Batam.<\\/div><div><br><\\/div><div>Terima kasih kepada seluruh pemegang saham, Komisaris, Direksi, dan seluruh insan PT Pelayanan Energi Batam atas dedikasi, kolaborasi, dan komitmennya dalam mewujudkan kinerja perusahaan yang semakin baik.<\\/div><div>Bersama, kita terus menghadirkan energi yang andal untuk mendukung pertumbuhan dan masa depan Batam.<\\/div><div><br><\\/div><div>#PT PLN Batam #PTPelayananEnergiBatam #GoodCorporateGovernance #EnergiUntukPertumbuhan #ReliableEnergyForGrowth<\\/div>\",\"date\":\"2026-07-01\",\"imageSrc\":\"\\/assets\\/berita\\/berita\\/news-2.jpeg\",\"imageSourceType\":\"url\",\"imageFileName\":\"news-2.jpeg\",\"gallery\":[],\"badge\":\"\"},{\"id\":\"legacy_news_1\",\"title\":\"PT Pelayanan Energi Batam Realisasikan Penyembelihan dan Distribusi Hewan Qurban Idul Adha 1447 H\",\"subtitle\":\"Dalam rangka memperingati Hari Raya Idul Adha 1447 H, PT Pelayanan Energi Batam (PEB) telah melaksanakan kegiatan penyembelihan dan pendistribusian hewan qurban pada Kamis, 28 Mei 2026 di halaman Kantor PT Pelayanan Energi Batam.\",\"date\":\"2026-05-28\",\"imageSrc\":\"\\/assets\\/berita\\/berita\\/news-1.jpeg\",\"imageSourceType\":\"url\",\"imageFileName\":\"news-1.jpeg\",\"gallery\":[{\"id\":\"qurban-g-1\",\"type\":\"image\",\"url\":\"\\/assets\\/berita\\/qurban\\/01.jpg\",\"sourceType\":\"url\",\"fileName\":\"01.jpg\"},{\"id\":\"qurban-g-2\",\"type\":\"image\",\"url\":\"\\/assets\\/berita\\/qurban\\/02.jpg\",\"sourceType\":\"url\",\"fileName\":\"02.jpg\"},{\"id\":\"qurban-g-3\",\"type\":\"image\",\"url\":\"\\/assets\\/berita\\/qurban\\/03.jpg\",\"sourceType\":\"url\",\"fileName\":\"03.jpg\"},{\"id\":\"qurban-g-4\",\"type\":\"image\",\"url\":\"\\/assets\\/berita\\/qurban\\/04.jpg\",\"sourceType\":\"url\",\"fileName\":\"04.jpg\"},{\"id\":\"qurban-g-5\",\"type\":\"image\",\"url\":\"\\/assets\\/berita\\/qurban\\/05.jpg\",\"sourceType\":\"url\",\"fileName\":\"05.jpg\"},{\"id\":\"qurban-g-6\",\"type\":\"image\",\"url\":\"\\/assets\\/berita\\/qurban\\/06.jpg\",\"sourceType\":\"url\",\"fileName\":\"06.jpg\"},{\"id\":\"qurban-g-7\",\"type\":\"image\",\"url\":\"\\/assets\\/berita\\/qurban\\/07.jpg\",\"sourceType\":\"url\",\"fileName\":\"07.jpg\"},{\"id\":\"qurban-g-8\",\"type\":\"image\",\"url\":\"\\/assets\\/berita\\/qurban\\/08.jpg\",\"sourceType\":\"url\",\"fileName\":\"08.jpg\"},{\"id\":\"qurban-g-9\",\"type\":\"image\",\"url\":\"\\/assets\\/berita\\/qurban\\/09.jpg\",\"sourceType\":\"url\",\"fileName\":\"09.jpg\"},{\"id\":\"qurban-g-10\",\"type\":\"image\",\"url\":\"\\/assets\\/berita\\/qurban\\/10.jpg\",\"sourceType\":\"url\",\"fileName\":\"10.jpg\"},{\"id\":\"qurban-g-11\",\"type\":\"image\",\"url\":\"\\/assets\\/berita\\/qurban\\/11.jpg\",\"sourceType\":\"url\",\"fileName\":\"11.jpg\"},{\"id\":\"qurban-g-12\",\"type\":\"image\",\"url\":\"\\/assets\\/berita\\/qurban\\/12.jpg\",\"sourceType\":\"url\",\"fileName\":\"12.jpg\"},{\"id\":\"qurban-g-13\",\"type\":\"image\",\"url\":\"\\/assets\\/berita\\/qurban\\/13.jpg\",\"sourceType\":\"url\",\"fileName\":\"13.jpg\"},{\"id\":\"qurban-g-14\",\"type\":\"image\",\"url\":\"\\/assets\\/berita\\/qurban\\/14.jpg\",\"sourceType\":\"url\",\"fileName\":\"14.jpg\"},{\"id\":\"qurban-g-15\",\"type\":\"image\",\"url\":\"\\/assets\\/berita\\/qurban\\/15.jpg\",\"sourceType\":\"url\",\"fileName\":\"15.jpg\"},{\"id\":\"qurban-g-16\",\"type\":\"image\",\"url\":\"\\/assets\\/berita\\/qurban\\/16.jpg\",\"sourceType\":\"url\",\"fileName\":\"16.jpg\"}],\"badge\":\"\"},{\"id\":\"1\",\"title\":\"Ekspansi Jaringan Listrik Baru di Kawasan Industri Kabil\",\"subtitle\":\"PT Pelayanan Energi Batam mengumumkan penyelesaian proyek infrastruktur krusial untuk mendukung kebutuhan industri manufaktur dan hilirisasi di kawasan Kabil, Batam. Pembangunan ini meliputi penambahan kapasitas transmisi dan distribusi energi yang andal dan ramah lingkungan guna mempercepat pertumbuhan kawasan industri terpadu.\",\"date\":\"28 April 2024\",\"imageSrc\":\"\\/storage\\/berita-images\\/PCXXPZBmpZi0yPhAOAqlnevL7PigGLJ9wWYJVAEL.jpg\",\"imageSourceType\":\"upload\",\"imageFileName\":\"Picture2.jpg\",\"gallery\":[],\"badge\":\"\"},{\"id\":\"e854765c-5134-45ca-aa3a-2b1c4779a499\",\"title\":\"Semangat Kemerdekaan ke-81: Bersama PEB, Berkarya untuk Indonesia\",\"subtitle\":\"Memperingati Hari Ulang Tahun ke-81 Republik Indonesia, PT Pelayanan Energi Batam mengajak seluruh insan perusahaan untuk meneruskan semangat perjuangan melalui kerja nyata, kolaborasi, dan dedikasi. Semangat kemerdekaan menjadi pengingat untuk terus memberikan pelayanan terbaik serta berkontribusi bagi kemajuan Batam dan Indonesia.\",\"date\":\"2026-08-17\",\"imageSrc\":\"\\/storage\\/berita-images\\/WGEK4ukTGaWOyR7BwS9ci5iCKAIZu8hNv5TtJMFv.jpg\",\"imageSourceType\":\"upload\",\"imageFileName\":\"WhatsApp Image 2026-11-10 at 13.56.30.jpeg\",\"gallery\":[{\"id\":\"1794294029546\",\"type\":\"video\",\"url\":\"https:\\/\\/www.instagram.com\\/reel\\/DcDF9jAzpV2\\/?mdxt=dmVvbzQ1NmJqaHMx\",\"sourceType\":\"url\",\"fileName\":null}],\"badge\":\"\"},{\"id\":\"aa1ff09f-18b2-46d9-ac9f-1022391c3966\",\"title\":\"HUT ke-12 PEB: Merayakan Kebersamaan, Memperkuat Sinergi untuk Terus Bertumbuh\",\"subtitle\":\"PT Pelayanan Energi Batam merayakan hari ulang tahun ke-12 dengan penuh rasa syukur dan semangat kebersamaan. Perayaan ini menjadi momentum untuk mengapresiasi dedikasi seluruh insan PEB, mempererat hubungan, serta membangun semangat baru dalam memberikan pelayanan terbaik.<div><br><\\/div><div>Isi Berita<\\/div><div>PT Pelayanan Energi Batam (PEB) memperingati hari ulang tahun ke-12 dalam suasana hangat, meriah, dan penuh kekeluargaan. Momen istimewa ini menjadi kesempatan untuk mensyukuri perjalanan perusahaan sekaligus menghargai kontribusi setiap insan yang telah menjadi bagian dari pertumbuhan PEB.<\\/div><div><br><\\/div><div>Dua belas tahun perjalanan PEB dibangun melalui kerja keras, kolaborasi, dan komitmen bersama. Setiap tantangan dan pencapaian menjadi bagian dari proses yang mendorong perusahaan untuk terus belajar, beradaptasi, dan meningkatkan kualitas pelayanan.<\\/div><div><br><\\/div><div>Semangat kebersamaan terasa dalam perayaan yang mempertemukan keluarga besar PEB. Dekorasi bernuansa biru dan emas, senyum para peserta, serta kemeriahan pembagian hadiah turut mewarnai suasana. Foto bersama menjadi kenangan atas kebahagiaan yang dibagikan dalam peringatan hari jadi perusahaan.<\\/div><div><br><\\/div><div>Lebih dari sekadar perayaan, HUT ke-12 menjadi momentum untuk memperkuat sinergi dan rasa memiliki terhadap perusahaan. Hubungan yang erat antarkaryawan menjadi bekal penting untuk membangun lingkungan kerja yang saling mendukung dan bergerak menuju tujuan bersama.<\\/div><div><br><\\/div><div>Memasuki usia ke-12, PEB membawa semangat untuk terus bertumbuh, meningkatkan profesionalisme, dan memberikan kontribusi bagi kemajuan Batam. Dengan kolaborasi yang semakin kuat, PEB siap melanjutkan perjalanan dan menyambut peluang di masa depan.<\\/div><div><br><\\/div><div>Terima kasih kepada seluruh karyawan, mitra, dan pemangku kepentingan atas kepercayaan serta dukungan yang menyertai perjalanan PT Pelayanan Energi Batam.<\\/div><div><br><\\/div><div>Selamat ulang tahun ke-12, PT Pelayanan Energi Batam. Terus bersinergi, berkarya, dan tumbuh bersama!<\\/div>\",\"date\":\"2026-09-03\",\"imageSrc\":\"\\/storage\\/berita-images\\/crSV6prZanOxvyWgpGN95RQgGc5TYzQb6v0kSQ6y.jpg\",\"imageSourceType\":\"upload\",\"imageFileName\":\"WhatsApp Image 2026-11-10 at 13.57.31.jpeg\",\"gallery\":[{\"id\":\"1794295495188\",\"type\":\"video\",\"url\":\"https:\\/\\/www.instagram.com\\/reel\\/DdA1uxtTMTD\\/?exln=b21kOHNzNXJxMDFx\",\"sourceType\":\"url\",\"fileName\":null}],\"badge\":\"\"}]','2026-08-12 21:54:01','2026-11-10 01:21:25');
/*!40000 ALTER TABLE `berita_sections` ENABLE KEYS */;
UNLOCK TABLES;

