INSERT INTO `daftar_pengadaans` VALUES (1,'Daftar Pengadaan','[\"Tender Terbuka\",\"Beauty Contest\",\"Seleksi Mitra\",\"Pengumuman Pemenang\"]','[{\"id\":\"legacy_event_45\",\"title\":\"Tender Terbuka Pekerjaan Pembangunan Turap/Talud Area Longsoran KP21\",\"status\":\"TUTUP\",\"isArchived\":true,\"startDate\":\"2022-06-29\",\"endDate\":\"2022-07-08\",\"date\":\"2022-06-29\",\"location\":\"Tanjung Batu, Kalimantan Timur\",\"category\":\"Tender Terbuka\",\"imageSrc\":\"/storage/daftar-pengadaan-images/event-45.jpg\",\"bannerImage\":\"/storage/daftar-pengadaan-images/event-banner-45.jpg\",\"imageSourceType\":\"upload\",\"deskripsi\":\"<p  ><span >Sehubungan akan\\r\\ndilakukan Tender Terbuka Pekerjaan tersebut di atas di PT Pelayanan Energi\\r\\nBatam (PT PEB) dengan&nbsp;<b>Pascakualifikasi,&nbsp;</b>Pelaksana Pengadaan\\r\\nBarang/Jasa PT PEB yang berkedudukan di Graha Energi Jl, Brigjen Katamso KM 8\\r\\nTanjung Uncang, mengundang Calon Penyedia Barang/Jasa mengikuti pelelangan\\r\\nPekerjaan Pembangunan Turap/Talud Area Longsoran KP21.</span></p><p  ><b><span >&nbsp;</span></b><span ></span></p><p  ><b><span >Tanggal/Waktu\\r\\nPendaftaran:</span></b><span ></span></p><p  ><span >Rabu, 29 Juni 2022 s.d\\r\\n08 Juli 2022, pukul 09.00 s.d 16.00 WIB</span></p><p  ><span >&nbsp;</span></p><p  ><b><span >Syarat-syarat\\r\\npendaftaran:</span></b><span ></span></p><p  ><!--[if !supportLists]--><span >1.<span >&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\\r\\n</span></span><!--[endif]--><span >Calon Penyedia Barang/Jasa merupakan suatu perusahaan lokal/dalam\\r\\nnegeri berbadan hukum Perseroan Terbatas (PT)/gabungan Perseroan Terbatas\\r\\n(PT)/Konsorsium/<i>Joint Operation</i>/Kerja Sama Operasi.</span><span ></span></p><p  ><!--[if !supportLists]--><span >2.<span >&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\\r\\n</span></span><!--[endif]--><span >&nbsp;</span><span >Memiliki Surat Izin Usaha Perdagangan (SIUP) yang masih berlaku.</span><span ></span></p><p  ><!--[if !supportLists]--><span >3.<span >&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\\r\\n</span></span><!--[endif]--><span >Nomor Induk Berusaha (NIB) yang masih berlaku.</span><span ></span></p><p  ><!--[if !supportLists]--><span >4.<span >&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\\r\\n</span></span><!--[endif]--><span >Memiliki Surat Izin Usaha Jasa Konstruksi&nbsp;<i>dan/atau</i>&nbsp;Sertifikasi\\r\\nBadan Usaha Jasa Konstruksi yang masih berlaku.</span><span ></span></p><p  ><!--[if !supportLists]--><span >5.<span >&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\\r\\n</span></span><!--[endif]--><span >Memiliki pengalaman yang berkaitan dengan Pekerjaan EPCC/EPCI\\r\\nminimal 2 (dua) kali dalam rentang waktu 5 (lima) tahun terakhir yang\\r\\ndibuktikan dengan melampirkan copy kontrak dan/atau BASTP dan/atau bukti\\r\\npenyelesaian pekerjaan.</span><span ></span></p><p  ><!--[if !supportLists]--><span >6.<span >&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\\r\\n</span></span><!--[endif]--><span >Memiliki&nbsp;<i>Rating</i>&nbsp;Keuangan dengan&nbsp;<i>rating\\r\\nFinancial Strength Indicators</i>&nbsp;minimal 3A yang dikeluarkan oleh PT\\r\\nD&amp;B Indonesia atau perusahaan/lembaga&nbsp;<i>rating</i>&nbsp;sejenis yang\\r\\nmemiliki kompetensi dan reputasi setara, dan/atau salinan Laporan Keuangan\\r\\nPerusahaan tahun terakhir yang memadai dan telah di Audit oleh Akuntan Publik.</span><span ></span></p><p  ><!--[if !supportLists]--><span >7.<span >&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\\r\\n</span></span><!--[endif]--><span >Syarat Pendaftaran nomor 2, 3, 4, dan 5 disampaikan ke PT PEB\\r\\nmelalui&nbsp;<b><i>email :&nbsp;</i></b></span><a href=\\\"mailto:proc@peb.co.id\\\"><b><i><span >proc@peb.co.id</span></i></b></a><b><span >.</span></b><span ></span></p><p  ><!--[if !supportLists]--><span >8.<span >&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\\r\\n</span></span><!--[endif]--><span >Calon Penyedia Barang/Jasa yang telah diverifikasi akan dikirimkan\\r\\nDokumen Tender/RKS melalui&nbsp;<i>email.</i></span><span ></span></p><p  ><span >Jadwal Penjelasan&nbsp;<i>(Aanwizjing)</i>&nbsp;Dokumen Tender/RKS\\r\\nuntuk Calon Penyedia Barang/Jasa yang telah diverifikasi, akan dilaksanakan\\r\\nSenin, 04 Juli 2022 Pukul 10.00 WIB s.d Selesai.</span></p><p  ><span >Mohon menyampaikan surat kuasa beserta&nbsp;<i>copy</i>&nbsp;KTP\\r\\npemberi dan penerima kuasa jika rapat penjelasan tidak dihadiri oleh pimpinan\\r\\nperusahaan.</span></p><p  ><span >&nbsp;</span></p><p  ><span >Demikian\\r\\nPengumuman ini disampaikan untuk diketahui sebagaimana mestinya.</span></p><p  ><span >Batam, 29\\r\\nJuni 2022<br>\\r\\n<!--[if !supportLineBreakNewLine]--><br>\\r\\n<!--[endif]--></span></p><p  ><span >Pelaksana\\r\\nPengadaan&nbsp;PT Pelayanan Energi Batam</span></p><p  ><span >Gedung\\r\\nGraha Energi, Jl Brigjen Katamso KM 8, Tanjung Uncang Batam</span></p><p  ><span >Telp.\\r\\n0778-736 1031, Email: proc@peb.co.id<br>\\r\\n<!--[if !supportLineBreakNewLine]--><br>\\r\\n<!--[endif]--></span></p><p>\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n</p><table  border=\\\"1\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" width=\\\"795\\\" style=\\\"width: 596.25pt; border: none;\\\">\\r\\n <tbody><tr>\\r\\n  <td valign=\\\"top\\\" >\\r\\n  <p  ><b><span >Pengumuman\\r\\n  dapat di unduh pada&nbsp;<i>link&nbsp;</i>berikut :</span></b><span >&nbsp;</span><a href=\\\"https://drive.google.com/file/d/1tCy9qhvgjg2vqCSfP5gsYJQxpKOI-VZQ/view?usp=sharing\\\" target=\\\"_blank\\\"><b><span >Download</span></b></a><span ></span></p>\\r\\n  </td>\\r\\n </tr>\\r\\n</tbody></table>\",\"syaratList\":[{\"id\":\"syarat_event_45_1\",\"text\":\"1.      Calon Penyedia Barang/Jasa merupakan suatu perusahaan lokal/dalam negeri berbadan hukum Perseroan Terbatas (PT)/gabungan Perseroan Terbatas (PT)/Konsorsium/Joint Operation/Kerja Sama Operasi.\"},{\"id\":\"syarat_event_45_2\",\"text\":\"2.       Memiliki Surat Izin Usaha Perdagangan (SIUP) yang masih berlaku.\"},{\"id\":\"syarat_event_45_3\",\"text\":\"3.      Nomor Induk Berusaha (NIB) yang masih berlaku.\"},{\"id\":\"syarat_event_45_4\",\"text\":\"4.      Memiliki Surat Izin Usaha Jasa Konstruksi dan/atau Sertifikasi Badan Usaha Jasa Konstruksi yang masih berlaku.\"},{\"id\":\"syarat_event_45_5\",\"text\":\"5.      Memiliki pengalaman yang berkaitan dengan Pekerjaan EPCC/EPCI minimal 2 (dua) kali dalam rentang waktu 5 (lima) tahun terakhir yang dibuktikan dengan melampirkan copy kontrak dan/atau BASTP dan/atau bukti penyelesaian pekerjaan.\"},{\"id\":\"syarat_event_45_6\",\"text\":\"6.      Memiliki Rating Keuangan dengan rating Financial Strength Indicators minimal 3A yang dikeluarkan oleh PT D&B Indonesia atau perusahaan/lembaga rating sejenis yang memiliki kompetensi dan reputasi setara, dan/atau salinan Laporan Keuangan Perusahaan tahun terakhir yang memadai dan telah di Audit oleh Akuntan Publik.\"},{\"id\":\"syarat_event_45_7\",\"text\":\"7.      Syarat Pendaftaran nomor 2, 3, 4, dan 5 disampaikan ke PT PEB melalui email : proc@peb.co.id.\"},{\"id\":\"syarat_event_45_8\",\"text\":\"8.      Calon Penyedia Barang/Jasa yang telah diverifikasi akan dikirimkan Dokumen Tender/RKS melalui email.\"}],\"dokumenList\":[{\"id\":\"doc_event_45_1\",\"name\":\"Dokumen Pengumuman Pengadaan\",\"fileSize\":\"Tautan Resmi Google Drive\",\"sourceType\":\"url\",\"fileUrl\":\"https://drive.google.com/file/d/1tCy9qhvgjg2vqCSfP5gsYJQxpKOI-VZQ/view?usp=sharing\",\"fileName\":\"Dokumen-Pengumuman-45\"}],\"mapsMode\":\"embed\",\"mapsEmbedUrl\":\"<iframe src=\\\"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d8508.666458164911!2d118.08440735978051!3d2.27759563999978!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3212885fd00f5ce3%3A0xbee349a23fbd5cd7!2sTj.%20Batu%2C%20Kec.%20Pulau%20Derawan%2C%20Kabupaten%20Berau%2C%20Kalimantan%20Timur!5e0!3m2!1sid!2sid!4v1662462384230!5m2!1sid!2sid\\\" width=\\\"600\\\" height=\\\"450\\\" style=\\\"border:0;\\\" allowfullscreen=\\\"\\\" loading=\\\"lazy\\\" referrerpolicy=\\\"no-referrer-when-downgrade\\\"></iframe>\",\"mapsKoordinat\":\"\",\"mapsLabel\":\"Tanjung Batu, Kalimantan Timur\"},{\"id\":\"legacy_event_46\",\"title\":\"Tender Terbuka Pengadaan Layanan Total Solusi Penyediaan PLTS Atap di Batam\",\"status\":\"TUTUP\",\"isArchived\":true,\"startDate\":\"2022-09-06\",\"endDate\":\"2022-09-14\",\"date\":\"2022-09-06\",\"location\":\"Batam\",\"category\":\"Tender Terbuka\",\"imageSrc\":\"/storage/daftar-pengadaan-images/event-46.jpg\",\"bannerImage\":\"/storage/daftar-pengadaan-images/event-banner-46.jpg\",\"imageSourceType\":\"upload\",\"deskripsi\":\"<p  ><span >SehubunganÂ akan dilakukan Tender Terbuka Pekerjaan tersebut\\r\\ndi atas di PT Pelayanan Energi Batam (PT PEB) denganÂ <b>Pascakualifikasi,Â </b>Pelaksana\\r\\nPengadaan Barang/Jasa PT PEB yang berkedudukan di Graha Energi Jl, Brigjen\\r\\nKatamso KM 8 Tanjung Uncang, mengundang Penyedia Barang/Jasa mengikuti Tender\\r\\nâ€œPengadaan Layanan Total Solusi Penyediaan PLTS Atap di Batam\\\".</span><span ></span></p><p  ><b><span >Â </span></b><span ></span></p><p  ><b><span >Tanggal/Waktu Pendaftaran:</span></b><span ></span></p><p  ><span >Selasa,\\r\\n06 September 2022 s.d 14 September 2022, pukul 09.00 s.d 16.00 WIB</span></p><p  ><span >Â </span></p><p  ><b><span >Syarat-syarat pendaftaran:</span></b><span >Â </span><span ></span></p><p  ><!--[if !supportLists]--><span >1.<span Times New Roman\\\";\\\">Â Â Â Â Â Â  </span></span><!--[endif]--><span >Calon\\r\\nPenyedia Barang/Jasa merupakan suatu perusahaan lokal/dalam negeri berbadan\\r\\nhukum Perseroan Terbatas (PT)/gabungan Perseroan Terbatas (PT)/Konsorsium/<i>Joint\\r\\nOperation</i>/Kerja Sama Operasi.</span></p><p  ><!--[if !supportLists]--><span >2.<span Times New Roman\\\";\\\">Â Â Â Â Â Â  </span></span><!--[endif]--><span >Memiliki\\r\\nNomor Induk Berusaha (NIB) yang masih berlaku.</span></p><p  ><!--[if !supportLists]--><span >3.<span Times New Roman\\\";\\\">Â Â Â Â Â Â  </span></span><!--[endif]--><span >Memiliki\\r\\nSertifikat Badan Usaha Jasa Penunjang Tenaga Listrik (SBUJPTL) yang terkait\\r\\ndenganÂ Jenis Usaha Pembangunan dan Pemasangan Instalasi Tenaga Listrik,\\r\\nBidang Pembangkitan Tenaga Listrik Subbidang Pembangkit Listrik Tenaga Energi\\r\\nBaru Lainnya dan Tenaga Energi Terbarukan Lainnya (PLTS) yang masih berlaku\\r\\ndengan minimal kualifikasi menengah.</span></p><p  ><!--[if !supportLists]--><span >4.<span Times New Roman\\\";\\\">Â Â Â Â Â Â  </span></span><!--[endif]--><span >Memiliki\\r\\nIzin Usaha Jasa Penunjang Tenaga Listrik (IUJPTL) bidang yang\\r\\nterkaitÂ sesuai dengan SBUJPTL yang masih berlaku dengan minimal\\r\\nkualifikasi menengah atauÂ memiliki Perizinan Berusaha Berbasis Risiko\\r\\nBidang Pembangkitan Tenaga Listrik.</span></p><p  ><!--[if !supportLists]--><span >5.<span Times New Roman\\\";\\\">Â Â Â Â Â Â  </span></span><!--[endif]--><span >Memiliki\\r\\npengalaman pada pekerjaan Pembangunan dan Pemasangan, Pengoperasian dan\\r\\nPemeliharaan Sistem PLTS Atap dengan minimal kapasitas 450 kWp dalam 3 (tiga)\\r\\ntahun terakhir terhitung sejak tanggal Dokumen Tender/RKS ini dengan melampirkan\\r\\ncopy kontrak dan/atau BASTP atau bukti penyelesaian pekerjaan.</span></p><p  ><!--[if !supportLists]--><span >6.<span Times New Roman\\\";\\\">Â Â Â Â Â Â  </span></span><!--[endif]--><span >Syarat\\r\\nPendaftaran nomor 2, 3, 4 dan 5 disampaikan ke PT PEB melaluiÂ <b><i>email\\r\\n:Â </i></b></span><a href=\\\"mailto:proc@peb.co.id\\\"><b><i><span >proc@peb.co.id</span></i></b></a><a href=\\\"mailto:proc@peb.co.id\\\"><span >.</span></a><span ></span></p><p  ><!--[if !supportLists]--><span >7.<span Times New Roman\\\";\\\">Â Â Â Â Â Â  </span></span><!--[endif]--><span >Calon\\r\\nPenyedia Barang/Jasa yang telah diverifikasi akan dikirimkan Dokumen Tender/RKS\\r\\nmelaluiÂ <i>email.</i></span></p><p  ><span >Jadwal PenjelasanÂ <i>(Aanwizjing)</i>Â Dokumen Tender/RKS\\r\\nuntuk Calon Penyedia Barang/Jasa yang telah diverifikasi, akan\\r\\ndilaksanakanÂ Jumat, 09 September 2022 Pukul 10.00 WIB s.d Selesai.</span></p><p  ><span >Mohon menyampaikan surat kuasa besertaÂ <i>copy</i>Â KTP\\r\\npemberi dan penerima kuasa jika rapat penjelasan tidak dihadiri oleh pimpinan\\r\\nperusahaan.</span></p><p  ><span >Demikian\\r\\nPengumuman ini disampaikan untuk diketahui sebagaimana mestinya.</span></p><p  ><span >Batam, 06\\r\\nSeptember 2022<br>\\r\\n<!--[if !supportLineBreakNewLine]--><br>\\r\\n<!--[endif]--></span></p><p  ><span >Pelaksana\\r\\nPengadaanÂ PT Pelayanan Energi Batam</span></p><p  ><span >Gedung\\r\\nGraha Energi, Jl Brigjen Katamso KM 8, Tanjung Uncang Batam</span></p><p  ><span >Telp.\\r\\n0778-736 1031, Email: proc@peb.co.id</span></p><p>\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n</p><table  border=\\\"1\\\" cellspacing=\\\"0\\\" cellpadding=\\\"0\\\" width=\\\"795\\\" style=\\\"width: 596.25pt; border: none;\\\">\\r\\n <tbody><tr>\\r\\n  <td valign=\\\"top\\\" >\\r\\n  <p  ><b><span >Pengumuman\\r\\n  dapat di unduh padaÂ <i>linkÂ </i>berikut :</span></b><span >Â </span><a href=\\\"https://drive.google.com/file/d/14ss-W_6mm5N0yLwWDIUixjD8rGqIkmEh/view?usp=sharing\\\" target=\\\"_blank\\\"><b><span >Download</span></b></a><span ></span></p>\\r\\n  </td>\\r\\n </tr>\\r\\n</tbody></table>\",\"syaratList\":[{\"id\":\"syarat_event_46_1\",\"text\":\"1.Â Â Â Â Â Â  Calon Penyedia Barang/Jasa merupakan suatu perusahaan lokal/dalam negeri berbadan hukum Perseroan Terbatas (PT)/gabungan Perseroan Terbatas (PT)/Konsorsium/Joint Operation/Kerja Sama Operasi.\"},{\"id\":\"syarat_event_46_2\",\"text\":\"2.Â Â Â Â Â Â  Memiliki Nomor Induk Berusaha (NIB) yang masih berlaku.\"},{\"id\":\"syarat_event_46_3\",\"text\":\"3.Â Â Â Â Â Â  Memiliki Sertifikat Badan Usaha Jasa Penunjang Tenaga Listrik (SBUJPTL) yang terkait denganÂ Jenis Usaha Pembangunan dan Pemasangan Instalasi Tenaga Listrik, Bidang Pembangkitan Tenaga Listrik Subbidang Pembangkit Listrik Tenaga Energi Baru Lainnya dan Tenaga Energi Terbarukan Lainnya (PLTS) yang masih berlaku dengan minimal kualifikasi menengah.\"},{\"id\":\"syarat_event_46_4\",\"text\":\"4.Â Â Â Â Â Â  Memiliki Izin Usaha Jasa Penunjang Tenaga Listrik (IUJPTL) bidang yang terkaitÂ sesuai dengan SBUJPTL yang masih berlaku dengan minimal kualifikasi menengah atauÂ memiliki Perizinan Berusaha Berbasis Risiko Bidang Pembangkitan Tenaga Listrik.\"},{\"id\":\"syarat_event_46_5\",\"text\":\"5.Â Â Â Â Â Â  Memiliki pengalaman pada pekerjaan Pembangunan dan Pemasangan, Pengoperasian dan Pemeliharaan Sistem PLTS Atap dengan minimal kapasitas 450 kWp dalam 3 (tiga) tahun terakhir terhitung sejak tanggal Dokumen Tender/RKS ini dengan melampirkan copy kontrak dan/atau BASTP atau bukti penyelesaian pekerjaan.\"},{\"id\":\"syarat_event_46_6\",\"text\":\"6.Â Â Â Â Â Â  Syarat Pendaftaran nomor 2, 3, 4 dan 5 disampaikan ke PT PEB melaluiÂ email :Â proc@peb.co.id.\"},{\"id\":\"syarat_event_46_7\",\"text\":\"7.Â Â Â Â Â Â  Calon Penyedia Barang/Jasa yang telah diverifikasi akan dikirimkan Dokumen Tender/RKS melaluiÂ email.\"}],\"dokumenList\":[{\"id\":\"doc_event_46_1\",\"name\":\"Dokumen Pengumuman Pengadaan\",\"fileSize\":\"Tautan Resmi Google Drive\",\"sourceType\":\"url\",\"fileUrl\":\"https://drive.google.com/file/d/14ss-W_6mm5N0yLwWDIUixjD8rGqIkmEh/view?usp=sharing\",\"fileName\":\"Dokumen-Pengumuman-46\"}],\"mapsMode\":\"embed\",\"mapsEmbedUrl\":\"<iframe src=\\\"https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d15956.11429813673!2d104.0186325!3d1.1400185!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0xba81b3ac630e232!2sPT.%20Sat%20Nusapersada%2C%20Tbk!5e0!3m2!1sid!2sid!4v1662460802753!5m2!1sid!2sid\\\" width=\\\"600\\\" height