INSERT INTO `daftar_servis_sections` VALUES (1,'Daftar Servis','[{\"id\":\"1\",\"title\":\"Enjiniring\",\"description\":\"PEB sendiri berfokus pada pembangkitan listrik untuk komunitas dan industri. PEB menggunakan metode yang berkaitan dengan kerangka teori dari bidang teknik elektro dan teknik mesin.\",\"imageSrc\":\"\\/storage\\/servis-daftar\\/uCWAzoa52GgIfZt5IPzWd6Gr5L17XnRARrFbJild.jpg\",\"imageSourceType\":\"upload\",\"imageFileName\":\"DSC04897.jpg\"},{\"id\":\"2\",\"title\":\"Pengadaan\",\"description\":\"PEB memanfaatkan pengetahuan dan ahli khusus untuk memastikan bahwa setiap fasilitas yang ada memiliki mesin, komponen, dan dapat beroperasi dengan aman.\",\"imageSrc\":\"\\/storage\\/servis-daftar\\/ydOlIY1f9F5vaz96IPo6P3cBzzEjjCsBQCl6tkG3.jpg\",\"imageSourceType\":\"upload\",\"imageFileName\":\"LAB01682.jpg\"},{\"id\":\"3\",\"title\":\"Konstruksi\",\"description\":\"Berpengalaman dalam konstruksi perpipaan & pipa saluran, pembangkit listrik dengan teknologi mutakhir dan inovasi berkelanjutan serta memastikan fasilitas yang ada mampu mencapai tingkat efisiensi tertinggi.\",\"imageSrc\":\"\\/storage\\/servis-daftar\\/uCs4yMnkL57ACwlm81ssabjVvf4ZUnu24iEaz46H.jpg\",\"imageSourceType\":\"upload\",\"imageFileName\":\"DSC09924.jpg\"},{\"id\":\"4\",\"title\":\"Instalasi\",\"description\":\"Kami bekerja sama dengan anda untuk membangun semua fasilitas dan intalasi terbaik, baik di area perkotaan yang padat maupun di daerah terpencil, untuk pipa gas atau pembangkit listrik.\",\"imageSrc\":\"\\/storage\\/servis-daftar\\/3KdgjwXMLARNqWK06wjEgEnLxDloxUCvacuBX3uQ.jpg\",\"imageSourceType\":\"upload\",\"imageFileName\":\"LAB05257.jpg\"},{\"id\":\"5\",\"title\":\"Operasional\",\"description\":\"PEB telah memastikan bahwa seluruh kontrol terkait pipeline atau power plant yang beroperasi akan selalu di monitoring selama 365 hari dalam 24 jam setiap tahun nya.\",\"imageSrc\":\"\\/storage\\/servis-daftar\\/UZ6P9ceYuOQwq9uysDd1C3wvJUCCscmA9MsixXaJ.jpg\",\"imageSourceType\":\"upload\",\"imageFileName\":\"LAB01803.jpg\"},{\"id\":\"6\",\"title\":\"Pemeliharaan\",\"description\":\"Kami akan memastikan bahwa pipeline gas dan power plan akan selalu berjalan dengan baik regularly, memastikan keandalan nya, memastikan jangka umur nya, biaya operasi yang lebih murah dan memastikan peningkatkan keamanan operasional\",\"imageSrc\":\"\\/storage\\/servis-daftar\\/SrkwHDgtyQYdp8TeJvPnAm2T6cj5LS3Uyf5TPkuE.jpg\",\"imageSourceType\":\"upload\",\"imageFileName\":\"LAB02143.jpg\"}]','2026-08-12 23:59:43','2026-11-08 20:27:57');
/*!40000 ALTER TABLE `daftar_servis_sections` ENABLE KEYS */;
UNLOCK TABLES;

