INSERT INTO `kebijakan_peb_sections` VALUES (1,'Kebijakan PEB','[{\"id\":\"tata-kelola\",\"title\":\"Tata Kelola Perusahaan\",\"subtitle\":\"Good Corporate Governance\",\"description\":\"Komitmen ini kami buat dengan penuh kesadaran dan rasa tanggung jawab karena kami yakin bahwa pengelolaan perusahaan sesuai dengan prinsip-prinsip standar yang tinggi untuk Good Corporate Governance dan best practice akan memberikan kemaslahatan bagi semua pihak serta mewujudkan kehidupan dengan kualitas yang lebih baik.\",\"signedBy\":\"PT Pelayanan Energi Batam\",\"role\":\"Direksi\",\"date\":\"Batam, 12 Oktober 2017\",\"fileUrl\":null},{\"id\":\"manajemen-risiko\",\"title\":\"Manajemen Risiko\",\"subtitle\":\"Risk Management Policy\",\"description\":\"PT Pelayanan Energi Batam (PT PEB) berkomitmen untuk melakukan pengelolaan atas risiko-risiko yang akan dihadapi dalam setiap proses bisnis perusahaan dalam rangka mencapai sasaran dan memenuhi kepatuhan terhadap Good Corporate Governance (GCG) yang dicanangkan oleh Pemerintah Republik Indonesia.\",\"signedBy\":\"ROSA DARMAN\",\"role\":\"Direktur\",\"date\":\"Batam, 01 Oktober 2024\",\"fileUrl\":null},{\"id\":\"sistem-manajemen\",\"title\":\"Sistim Manajemen Terpadu\",\"subtitle\":\"Integrated Management System Policy\",\"description\":\"PT Pelayanan Energi Batam (PT PEB) sebagai Badan Hukum Pemilik Izin Manufaktur\\/Fabrikasi Penunjang Industri Minyak & Gas dan Manajemen Gas Transportasi Industri Lainnya. Berkomitmen untuk memenuhi kebutuhan dan melebihi Ekspektasi pelanggan, persyaratan perundangan melalui peningkatan berkelanjutan dan efisiensi biaya.\",\"signedBy\":\"PT Pelayanan Energi Batam\",\"role\":\"Direksi\",\"date\":\"Batam, 12 Oktober 2017\",\"fileUrl\":null}]','2026-08-13 00:05:04','2026-08-13 00:05:49');
/*!40000 ALTER TABLE `kebijakan_peb_sections` ENABLE KEYS */;
UNLOCK TABLES;

