INSERT INTO `laporan_keuangan_sections` VALUES (1,'Laporan Keuangan','Ikhtisar performa finansial per kuartal dan tahunan.','[{\"id\":\"1\",\"title\":\"Laporan Keuangan Konsolidasian 2023\",\"subtitle\":\"Laporan audit akhir tahun yang mencakup seluruh entitas bisnis energi Batam.\",\"date\":\"15 Mar 2024\",\"badge\":\"Q4 2023\",\"imageSrc\":\"\\/assets\\/pengadaan\\/items\\/item1.png\",\"imageSourceType\":\"url\",\"poinUtamaList\":[{\"id\":\"1\",\"text\":\"Neraca Keuangan Audited menggambarkan pertumbuhan aset bersih perusahaan sebesar 12.4% YoY.\"},{\"id\":\"2\",\"text\":\"Laporan Laba Rugi menunjukkan peningkatan efisiensi biaya transmisi gas dan penguatan laba operasional.\"},{\"id\":\"3\",\"text\":\"Kajian Arus Kas terperinci mengenai alokasi investasi proyek energi surya strategis di Sekupang.\"},{\"id\":\"4\",\"text\":\"Opini Auditor Independen dengan hasil Wajar Tanpa Pengecualian (WTP) atas laporan konsolidasi.\"}],\"dokumenList\":[{\"id\":\"d1\",\"name\":\"Dokumen Laporan Keuangan Audited 2024\",\"fileSize\":\"2.4 MB\",\"sourceType\":\"url\",\"fileUrl\":\"#\"}]},{\"id\":\"2\",\"title\":\"Laporan Kinerja Kuartal III - 2023\",\"subtitle\":\"Analisis pertumbuhan operasional dan efisiensi energi periode Juli-September.\",\"date\":\"20 Nov 2023\",\"badge\":\"Q3 2023\",\"imageSrc\":\"\\/assets\\/pengadaan\\/items\\/item5.png\",\"imageSourceType\":\"url\",\"poinUtamaList\":[],\"dokumenList\":[]},{\"id\":\"3\",\"title\":\"Laporan Kinerja Kuartal II - 2023\",\"subtitle\":\"Data komprehensif mengenai realisasi anggaran dan pendapatan semester pertama.\",\"date\":\"15 Aug 2023\",\"badge\":\"Q2 2023\",\"imageSrc\":\"\\/assets\\/pengadaan\\/items\\/item3.png\",\"imageSourceType\":\"url\",\"poinUtamaList\":[],\"dokumenList\":[]},{\"id\":\"4\",\"title\":\"Laporan Kinerja Kuartal I - 2023\",\"subtitle\":\"Rangkuman inisiatif awal tahun dan target operasional 2023.\",\"date\":\"10 May 2023\",\"badge\":\"Q1 2023\",\"imageSrc\":\"\\/assets\\/pengadaan\\/items\\/item6.png\",\"imageSourceType\":\"url\",\"poinUtamaList\":[],\"dokumenList\":[]}]','2026-08-12 21:54:01','2026-08-12 21:54:01');
