INSERT INTO `laporan_tahunan_sections` VALUES (1,'Laporan Tahunan','Dokumentasi perjalanan tahunan kami dalam membangun energi berkelanjutan.','[{\"id\":\"1\",\"title\":\"Annual Report 2023: Powering Digital Batam\",\"subtitle\":\"Tinjauan mendalam tentang transformasi infrastruktur energi untuk mendukung pertumbuhan pusat data dan industri teknologi di Kepulauan Riau.\",\"badge\":\"BEST IN ENERGY SECTOR\",\"imageSrc\":\"\\/assets\\/pengadaan\\/items\\/item2.png\",\"imageSourceType\":\"url\",\"fileUrl\":\"#\",\"fileSourceType\":\"url\",\"fileName\":\"\",\"fileSize\":\"24.5 MB\"},{\"id\":\"2\",\"title\":\"Annual Report 2022: Resilient Energy\",\"subtitle\":\"Bagaimana kami beradaptasi dan tetap tangguh dalam menyediakan energi yang handal di tengah tantangan ekonomi global pasca-pandemi.\",\"badge\":\"LEGACY & INNOVATION\",\"imageSrc\":\"\\/assets\\/pengadaan\\/items\\/item4.png\",\"imageSourceType\":\"url\",\"fileUrl\":\"#\",\"fileSourceType\":\"url\",\"fileName\":\"\",\"fileSize\":\"18.2 MB\"}]','[{\"id\":\"1\",\"title\":\"Sustainability Report 2023\",\"subtitle\":\"Green Energy Initiatives\",\"fileUrl\":\"#\",\"fileSourceType\":\"url\",\"fileName\":\"\",\"fileSize\":\"0 MB\"},{\"id\":\"2\",\"title\":\"Tata Kelola Perusahaan (GCG)\",\"subtitle\":\"Pedoman Etika & Integritas\",\"fileUrl\":\"#\",\"fileSourceType\":\"url\",\"fileName\":\"\",\"fileSize\":\"0 MB\"},{\"id\":\"3\",\"title\":\"Laporan CSR 2023\",\"subtitle\":\"Pemberdayaan Masyarakat Lokal\",\"fileUrl\":\"#\",\"fileSourceType\":\"url\",\"fileName\":\"\",\"fileSize\":\"0 MB\"}]','2026-08-12 21:54:01','2026-08-12 21:54:01');
