INSERT INTO `layanan_section_berandas` VALUES (1,'Layanan Terbaik Akan Selalu Kami Berikan','[{\"id\":\"1\",\"icon\":\"Wrench\",\"title\":\"Enjiniring\",\"description\":\"PEB sendiri berfokus pada pembangkitan listrik untuk komunitas dan industri. PEB menggunakan metode yang berkaitan dengan kerangka teori dari bidang teknik elektro dan teknik mesin.\"},{\"id\":\"2\",\"icon\":\"BookText\",\"title\":\"Pengadaan\",\"description\":\"PEB memanfaatkan pengetahuan dan ahli khusus untuk memastikan bahwa setiap fasilitas yang ada memiliki mesin, komponen, dan dapat beroperasi dengan aman.\"},{\"id\":\"3\",\"icon\":\"Bolt\",\"title\":\"Konstruksi\",\"description\":\"Berpengalaman dalam konstruksi perpipaan & pipa saluran, pembangkit listrik dengan teknologi mutakhir dan inovasi berkelanjutan serta memastikan bahwa fasilitas yang ada mampu mencapai tingkat efisiensi tertinggi.\"},{\"id\":\"4\",\"icon\":\"Server\",\"title\":\"Instalasi\",\"description\":\"Kami bekerja sama dengan anda untuk membangun semua fasilitas dan intalasi terbaik, baik di area perkotaan yang padat maupun di daerah terpencil, untuk pipa gas atau pembangkit listrik.\"},{\"id\":\"5\",\"icon\":\"Zap\",\"title\":\"Operasional\",\"description\":\"PEB telah memastikan bahwa seluruh kontrol terkait pipeline atau power plant yang beroperasi akan selalu di monitoring selama 365 hari dalam 24 jam setiap tahun nya.\"},{\"id\":\"6\",\"icon\":\"RefreshCw\",\"title\":\"Pemeliharaan\",\"description\":\"Kami akan memastikan bahwa pipeline gas dan power plan akan selalu berjalan dengan baik regularly, memastikan keandalan nya, memastikan jangka umur nya, biaya operasi yang lebih murah dan memastikan peningkatkan keamanan operasional.\"}]','2026-08-12 22:18:52','2026-08-12 22:18:52');
/*!40000 ALTER TABLE `layanan_section_berandas` ENABLE KEYS */;
UNLOCK TABLES;

