INSERT INTO `portfolio_section_berandas` VALUES (1,'Portofolio','Komitmen kami dalam menghadirkan solusi energi berkelanjutan tercermin dalam rekam jejak proyek strategis di seluruh Indonesia.','Mari bekerja sama','[{\"id\":\"1\",\"title\":\"PEMBANGKIT LISTRIK TENAGA GAS BATAM\",\"category\":\"OPERASIONAL & PEMELIHARAAN\",\"year\":\"2024\",\"image\":\"\\/assets\\/beranda\\/portfolio\\/project-1.png\",\"imageSource\":\"url\"},{\"id\":\"2\",\"title\":\"SOLAR HYBRID SYSTEM TANJUNG UNCANG\",\"category\":\"ENERGI TERBARUKAN\",\"year\":\"2025\",\"image\":\"\\/assets\\/beranda\\/portfolio\\/project-2.png\",\"imageSource\":\"url\"},{\"id\":\"3\",\"title\":\"TRANSMISI 150KV ANTAR PULAU\",\"category\":\"INFRASTRUKTUR JARINGAN\",\"year\":\"2026\",\"image\":\"\\/assets\\/beranda\\/portfolio\\/project-3.png\",\"imageSource\":\"url\"},{\"id\":\"4\",\"title\":\"PROYEK PENGEMBANGAN PLTS CIRATA\",\"category\":\"ENERGI TERBARUKAN\",\"year\":\"2024\",\"image\":\"\\/assets\\/beranda\\/portfolio\\/project-1.png\",\"imageSource\":\"url\"},{\"id\":\"5\",\"title\":\"MAINTENANCE TURBIN GAS PLTGU\",\"category\":\"OPERASIONAL & PEMELIHARAAN\",\"year\":\"2025\",\"image\":\"\\/assets\\/beranda\\/portfolio\\/project-2.png\",\"imageSource\":\"url\"}]','2026-08-12 22:19:45','2026-09-13 20:16:14');
