INSERT INTO `profil_section_tentangs` VALUES (1,'PT Pelayanan\r\nEnergi Batam','Sebagai anak perusahaan PLN Batam dan bagian dari PLN Group, PT Pelayanan Energi Batam (PEB) didirikan pada 03 September 2014 dengan visi untuk menjadi mitra terpercaya dalam industri energi. Sejak awal, kami telah menunjukkan komitmen yang kuat dalam mendukung pembangunan (Engineering, Procurement, Construction and Installation/EPCI) dan pemeliharaan infrastruktur gas di wilayah Batam dan sekitarnya.','/assets/tentang-kami/about/about.png','url',NULL,'12+','Tahun pengalaman dalam industri energi','Lokasi Kami','Batam, Kepulauan Riau','koordinat','1.1301,104.0529',NULL,'2026-08-12 23:42:17','2026-11-10 01:01:00');
