INSERT INTO `roles` VALUES (1,'user','User','Pengguna biasa dengan akses baca saja.','text-blue-400','{\"view_dashboard\":true,\"view_content\":true,\"edit_content\":false,\"manage_gallery\":false,\"manage_procurement\":false,\"manage_portfolio\":false,\"manage_reports\":false,\"manage_users\":false,\"manage_roles\":false,\"manage_settings\":false,\"publish_content\":false,\"delete_content\":false}','2026-08-12 21:54:00','2026-08-12 21:54:00'),(2,'admin','Admin','Administrator dengan akses pengelolaan konten penuh.','text-admin-accent','{\"view_dashboard\":true,\"view_content\":true,\"edit_content\":true,\"manage_gallery\":true,\"manage_procurement\":true,\"manage_portfolio\":true,\"manage_reports\":true,\"manage_users\":true,\"manage_roles\":false,\"manage_settings\":false,\"publish_content\":true,\"delete_content\":false}','2026-08-12 21:54:00','2026-11-09 18:52:21'),(3,'super_admin','Super Admin','Akses penuh ke seluruh sistem tanpa batasan.','text-amber-400','{\"view_dashboard\":true,\"view_content\":true,\"edit_content\":true,\"manage_gallery\":true,\"manage_procurement\":true,\"manage_portfolio\":true,\"manage_reports\":true,\"manage_users\":true,\"manage_roles\":true,\"manage_settings\":true,\"publish_content\":true,\"delete_content\":true}','2026-08-12 21:54:00','2026-08-12 21:54:00'),(4,'admin_pengadaan','Admin Pengadaan','Mengelola dan mempublikasikan Pengadaan secara langsung. Tidak memiliki akses modul CMS lainnya.','text-admin-accent','{\"manage_procurement\":true}','2026-11-03 00:22:32','2026-11-03 00:22:32');
