DROP TABLE IF EXISTS `seo_metas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `seo_metas` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `page_type` varchar(255) NOT NULL,
  `meta_title` varchar(255) NOT NULL,
  `meta_description` text NOT NULL,
  `meta_keywords` varchar(255) DEFAULT NULL,
  `author` varchar(255) DEFAULT NULL,
  `robots_index` varchar(255) NOT NULL DEFAULT 'index',
  `robots_follow` varchar(255) NOT NULL DEFAULT 'follow',
  `og_title` varchar(255) NOT NULL,
  `og_description` text NOT NULL,
  `og_image` varchar(2048) DEFAULT NULL,
  `image_source_type` varchar(255) NOT NULL DEFAULT 'url',
  `image_file_name` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `seo_metas_page_type_unique` (`page_type`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
