INSERT INTO `seo_metas` VALUES (1,'beranda','PT Pelayanan Energi Batam | Penyedia Solusi Energi Terintegrasi','PT Pelayanan Energi Batam (PEB) berkomitmen menyediakan energi yang andal, inovatif, dan berkelanjutan. Temukan informasi produk, inovasi, dan layanan kami.','energi batam, peb, pelayanan energi batam, energi terbarukan, gas batam, pln group','PT Pelayanan Energi Batam','index','follow','PT Pelayanan Energi Batam | Energi Bagi Negeri','Penyedia infrastruktur dan solusi energi terintegrasi terpercaya di Batam.','/assets/beranda/about/about.png','url','','2026-08-12 22:41:17','2026-08-12 22:41:17'),(2,'servis','Layanan Servis | PT Pelayanan Energi Batam','Jelajahi layanan servis lengkap PT Pelayanan Energi Batam: Enjiniring, Pengadaan, Konstruksi, Instalasi, Operasional, dan Pemeliharaan.','energi batam, peb, pelayanan energi batam, energi terbarukan, gas batam, pln group','PT Pelayanan Energi Batam','index','follow','Layanan Servis - PT Pelayanan Energi Batam','Solusi servis energi profesional dengan tim ahli berpengalaman di bidang enjiniring, konstruksi, dan operasional.','/assets/beranda/about/about.png','url','','2026-08-13 00:03:51','2026-08-13 00:03:51'),(3,'pengadaan','Pengadaan & Tender | PT Pelayanan Energi Batam','Informasi tender dan pengadaan barang/jasa PT Pelayanan Energi Batam. Temukan peluang kerjasama dan daftar pengadaan terbuka.','energi batam, peb, pelayanan energi batam, energi terbarukan, gas batam, pln group','PT Pelayanan Energi Batam','index','follow','Pengadaan & Tender - PT Pelayanan Energi Batam','Daftar tender dan pengadaan terbuka PT Pelayanan Energi Batam. Bergabunglah sebagai mitra pengadaan kami.','/assets/beranda/about/about.png','url',NULL,'2026-08-18 06:09:14','2026-08-19 20:50:55'),(4,'tentang','Tentang Kami | PT Pelayanan Energi Batam','Kenali lebih dekat PT Pelayanan Energi Batam, visi misi kami untuk memberikan layanan energi kelas dunia, serta profil tim kepemimpinan kami.','energi batam, peb, pelayanan energi batam, energi terbarukan, gas batam, pln group','PT Pelayanan Energi Batam','index','follow','Tentang Kami - PT Pelayanan Energi Batam','Transformasi berkelanjutan PT Pelayanan Energi Batam menuju penyedia energi hijau.','/assets/beranda/about/about.png','url','','2026-08-19 23:59:53','2026-08-19 23:59:53'),(5,'kebijakan','Kebijakan Korporat | PT Pelayanan Energi Batam','PT Pelayanan Energi Batam berkomitmen menjalankan tata kelola perusahaan yang bersih, aman, berintegritas, dan selaras dengan standar internasional.','energi batam, peb, pelayanan energi batam, energi terbarukan, gas batam, pln group','PT Pelayanan Energi Batam','index','follow','Kebijakan Korporat - PT Pelayanan Energi Batam','Komitmen tata kelola perusahaan yang transparan, berintegritas, dan sesuai standar ISO internasional.','/assets/beranda/about/about.png','url','','2026-08-21 00:08:40','2026-08-21 00:08:40'),(6,'galeri','Galeri Dokumentasi | PT Pelayanan Energi Batam','Eksplorasi dokumentasi visual komprehensif dari fasilitas, teknologi modern, serta keterlibatan aktif tim ahli PT Pelayanan Energi Batam.','energi batam, peb, pelayanan energi batam, energi terbarukan, gas batam, pln group','PT Pelayanan Energi Batam','index','follow','Galeri Dokumentasi - PT Pelayanan Energi Batam','Dokumentasi visual fasilitas dan kegiatan operasional PT Pelayanan Energi Batam di Batam.','/assets/beranda/about/about.png','url','','2026-08-21 00:08:51','2026-08-21 00:08:51'),(7,'laporan','Laporan & Publikasi | PT Pelayanan Energi Batam','Dokumentasi pertanggungjawaban publik, laporan tahunan, laporan keuangan audit, serta komitmen transparansi tata kelola PT Pelayanan Energi Batam.','energi batam, peb, pelayanan energi batam, energi terbarukan, gas batam, pln group','PT Pelayanan Energi Batam','index','follow','Laporan & Publikasi - PT Pelayanan Energi Batam','Laporan keuangan, laporan tahunan, dan publikasi resmi PT Pelayanan Energi Batam untuk transparansi publik.','/assets/beranda/about/about.png','url','','2026-08-21 00:09:08','2026-08-21 00:09:08'),(8,'berita','Berita & Acara | PT Pelayanan Energi Batam','Ikuti perkembangan terbaru, proyek strategis, dan pencapaian PT Pelayanan Energi Batam secara berkala.','energi batam, peb, pelayanan energi batam, energi terbarukan, gas batam, pln group','PT Pelayanan Energi Batam','index','follow','Berita & Acara - PT Pelayanan Energi Batam','Informasi dan berita terbaru dari PT Pelayanan Energi Batam.','/assets/beranda/about/about.png','url','','2026-08-21 00:09:13','2026-08-21 00:09:13'),(9,'portfolio','Portofolio Proyek | PT Pelayanan Energi Batam','Rekam jejak proyek infrastruktur energi kritis, enjiniring kelas dunia, dan pengadaan strategis PT Pelayanan Energi Batam di Batam.','energi batam, peb, pelayanan energi batam, energi terbarukan, gas batam, pln group','PT Pelayanan Energi Batam','index','follow','Portofolio Proyek - PT Pelayanan Energi Batam','Jelajahi portofolio proyek energi PT Pelayanan Energi Batam: gas infrastructure, solar energy, power plant, dan operations.','/assets/beranda/about/about.png','url','','2026-10-08 02:29:18','2026-10-08 02:29:18'),(10,'kontak','','','energi batam, peb, pelayanan energi batam, energi terbarukan, gas batam, pln group','PT Pelayanan Energi Batam','index','follow','','','/assets/beranda/about/about.png','url','','2026-11-10 00:31:43','2026-11-10 00:31:43');
